#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    if (n == 0) return n;

    // If no even is found, return n (sentinel: "not found")
    size_t best = n;

    #pragma omp parallel
    {
        size_t local_best = n;

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
            if ((x[static_cast<size_t>(i)] & 1) == 0) {
                local_best = static_cast<size_t>(i);
                break; // first even within this thread's chunk
            }
        }

        #pragma omp critical
        {
            if (local_best < best) best = local_best;
        }
    }

    return best;
}
